using System.Collections.Generic;

namespace AncientWarfare3.content.figures
{
    internal static class HistoricalFigureCardBiographiesPreQin
    {
        public static void AddTo(IDictionary<string, string> pEntries)
        {
            pEntries.Add("chu_huaiwang",
                "楚怀王（约前355年—前296年），芈姓，熊氏，名槐，楚国君主。父为楚威王，怀王任用佞臣令尹子兰、上官大夫靳尚，宠爱郑袖，为人利令智昏，国事日非。最后被秦昭襄王所骗，监禁于秦国至死，楚人皆悲之。秦朝末年，群雄并起，前208年反秦的民变领袖陈胜败亡后，当时反秦大将项梁（旧楚国将领项燕之子）立楚怀王之孙熊心为楚王，仍号「怀王」，以争取楚人民心，又称楚义帝。");
            pEntries.Add("chu_weiwang",
                "楚威王（？—前329年），芈姓，熊氏，名商，楚宣王之子，战国时期楚国着名国君，被称为楚国的中兴之主。他在位期间，楚国的疆域达到了最大规模，囊括了长江中下游以及支流众多的淮河流域。苏秦曾对楚威王说：“西有黔中、巫郡，东有夏州、海阳，南有洞庭、苍梧，北有陉塞、郇阳。地方五千余里，带甲百万，车千乘，骑万匹，粟支十年。");
            pEntries.Add("chu_zhuangwang",
                "楚庄王熊旅是春秋时期楚国君主，即位之初受到若敖氏等强宗牵制，经过平定斗越椒之乱才稳固王权。他重用孙叔敖整顿内政，在邲之战击败晋军，又北上洛邑问鼎，显示楚国争夺中原霸权的实力。楚庄王同时接受伍举、苏从等人的劝谏，后世以“三年不鸣，一鸣惊人”概括其由隐忍转向有为的统治。");
            pEntries.Add("ji_fa",
                "周武王（约前1076年—前1043年），姓姬，名发，西周创建者，第一代天子，青铜器铭文又名珷。他是西伯昌（后追尊文王）与太姒的嫡次子，其正妻为邑姜。传统上，周武王同尧、舜、禹、汤和周文王一向为后世儒家人物所尊崇的先秦明君。武王继承文王志业，约11世纪中期东征商朝，在牧野之战击败帝辛（纣王），建立周朝。");
            pEntries.Add("jin_wengong",
                "晋文公（前671年—前628年10月27日），姬姓，晋氏，名重（chóng）耳，晋献公之子，春秋时期着名的政治家，晋国国君，在位九年，在赵衰（赵国先祖）、狐偃、贾佗、先轸、魏武子（魏国先祖）、介之推等人的辅佐下，成为春秋五霸之一，开创了晋国长达一个多世纪的中原霸权，为后来的三晋（赵国、魏国、韩国）位列战国七雄奠定了基础。前671年，晋献公与戎族通婚，娶狐季姬，生下重耳。前665年，继母骊姬生下一子，取名奚齐，骊姬与优施通奸，淫乱后宫，两人开始排挤陷害申生、重耳、夷吾。在前665年，晋献公派重耳守护蒲城。");
            pEntries.Add("qi_huangong",
                "齐桓公（？—前643年10月7日），春秋时代齐国第十五位国君，姜姓，齐氏，名小白，齐僖公的儿子、齐襄公的弟弟。齐襄公和公孙无知相继死于内乱后，小白与公子纠争位成功，即国君位为齐桓公。桓公任管仲为相，推行改革，实行军政合一、兵民合一的制度，齐国逐渐强盛。他在位期间，还以国懿仲、高傒、管夷吾、仲孙湫、隰朋等人为执政。");
            pEntries.Add("qi_weiwang",
                "齐威王（约前378年—前320年），妫姓，田氏，名因齐，战国策作婴齐，出土文物作陈侯因齐（上次下月），田齐君主，为田齐桓公之子。在位初期，「好为淫乐长夜之饮，沈湎不治」，把政事交给卿大夫处理。后来采姬妾虞姬之言，重用即墨大夫，烹杀佞臣阿大夫，齐国得以大治。其后在能臣邹忌、田忌的辅助下，一度称王中原。");
            pEntries.Add("qin_bai_gui",
                "白圭活跃于战国时期，曾在魏国任职并以治水、经营和贸易见长。他提出“人弃我取，人取我与”的经营原则，善于根据年景、物价和供求囤积转运货物。后世常把他视为先秦商业思想的重要代表，其事迹反映战国商品交换和国家经济管理的发展。");
            pEntries.Add("qin_bai_qi",
                "白起（前332年？—前257年11月），白氏，又称公孙起，郿县（今陕西省眉县常兴镇白家村）人，战国时代军事家、秦国名将，兵家代表人物。白起担任秦国将领30多年，攻城70余座，歼灭大量敌军，被封为武安君。白起一生有伊阙之战、鄢郢之战、华阳之战、陉城之战和长平之战等胜利，《千字文》将白起与王翦、廉颇和李牧并称为战国四名将。后至唐朝位列武庙十哲之一。");
            pEntries.Add("qin_bao_shuya",
                "鲍叔牙（？—前644年），姒姓，鲍氏，亦称鲍叔、鲍子，春秋时代齐国大夫，颍上（今安徽省阜阳市颍上县）人。鲍叔牙是管仲的好友，早期管仲贫困，管仲占便宜他不以为意。后来管仲侍奉齐襄公的弟弟公子纠，鲍叔牙侍奉公子纠的弟弟公子小白。");
            pEntries.Add("qin_chunshen",
                "春申君黄歇早年出使秦国，以书信说服秦昭襄王停止攻楚，并设法护送太子熊完回国继位。楚考烈王任命他为令尹、封以淮北十二县，黄歇广招宾客并长期主持楚国军政，与信陵君等并称战国四公子。他后来改封江东，参与五国合纵攻秦；考烈王去世时，黄歇在宫门遭李园伏兵杀害。");
            pEntries.Add("qin_er_shi",
                "秦二世（约前230年—前207年10月1日），嬴姓，名胡亥，秦朝第二位皇帝，秦始皇第十八子。西元前210年，秦始皇出游南方，病死沙丘宫，随同出游的胡亥即位为二世皇帝。秦二世即位后，杀兄弟姐妹二十余人，赵高掌权，实行残暴统治，终于激起陈胜、吴广的大泽之变，山东六国旧公室也乘机各自复国。西元前207年赵高的女婿阎乐强逼胡亥自刎于望夷宫，卒年23岁。");
            pEntries.Add("qin_fan_chi",
                "樊须，字子迟，鲁人，孔子弟子。他大约比孔子年少三四十岁。前484年齐鲁稷曲之战，季康子派冉求率领左军，管周父御戎，樊须车右。樊迟曰：“非不能也，不信子也。");
            pEntries.Add("qin_fan_ju",
                "范雎原为魏国人，因被诬告通齐而遭毒打，逃入秦国后化名张禄向秦昭襄王进言。他提出“远交近攻”，主张先夺取邻近韩魏土地，并帮助秦王削弱宣太后、魏冉等外戚势力。范雎拜相封应侯后又举荐郑安平、王稽，但二人获罪使其政治地位受损，最终辞去相位。");
            pEntries.Add("qin_fanli",
                "范蠡（lǐ）（前536年10月22日—前448年），字少伯，又名鸱夷子皮、陶朱公，早年居楚时，尚未出仕，人称范伯。以居定陶（今山东省菏泽市定陶区）经商致富，广为世人所知，后代许多生意人皆供奉他的塑像，称之财神。传说佐越王勾践定计灭吴后与西施泛五湖而去，事见《越绝书》《吴越春秋》。范蠡出生于前536年10月22日（农历前536年 乙丑年 九月初一），春秋楚国宛地三户邑（今河南南阳淅川县大石桥乡至寺湾镇间）人，是历史上早期着名的政治家、军事家和经济学家。");
            pEntries.Add("qin_gongsun_long",
                "公孙龙（前320年—前250年），东周战国时期赵国人（今河北邯郸），传说字子秉，曾经做过平原君的门客，是名家的代表人物，以「白马非马」和「离坚白」等论点而着名。与公孙龙齐名的是另一名家惠施。高诱注《吕氏春秋》：谓龙为魏人，不知何据。平原君好养名家之学，公孙龙曾为平原君的食客，主张「白马非马」，期望以其辩才实现「正名实而化天下」。");
            pEntries.Add("qin_gongye_chang",
                "公冶长（前519年—前470年）字子长或子芝，春秋末年人物。他不但是孔子的弟子，同时也是孔子的女婿。《论语》记载，孔子评价他说：“可妻也；虽在缧绁之中，非其罪也。《史记·仲尼弟子列传》称其为“齐人，字子长”；《孔子家语·七十二弟子解》则称其为“鲁人，字子长”，并说他“为人能忍耻”。");
            pEntries.Add("qin_guan_zhong",
                "管仲（前725年—前645年），姬姓，管氏，名夷吾，字仲，以字行，谥敬，通称为管子、管夷吾、管敬仲，颍上（今安徽省颍上县）人，春秋时期法家代表人物。齐国的政治家，哲学家，与乐毅齐名，周穆王的后代。管仲虽然仅是齐国下卿，却被视为中国历史上宰相的典范，任内大兴改革，重视商业。《国语·齐语》、《史记·管晏列传》、《管子》、《左传》等都载有他的生活传记，《论语》中也有几处关于孔子对他的评论，北宋苏洵的《管仲论》也对管仲做出了分析和批判。");
            pEntries.Add("qin_hanfeizi",
                "韩非是战国末年韩国宗室公子，曾从荀子学习，与李斯同门，却因口吃而更擅长著述。他综合商鞅之法、申不害之术和慎到之势，主张君主依靠法令、权势与官僚考核治理国家，著述后编为《韩非子》。秦王嬴政赏识其文章并召他入秦，韩非却遭李斯、姚贾构陷下狱，最终被迫服毒而死。");
            pEntries.Add("qin_huiwenwang",
                "秦惠文王（前356年—前311年），又称秦惠王或秦惠文君，嬴姓，考古名駰，传世名驷，秦孝公之子，称王前为伯爵，称秦伯駰或秦伯驷。在位期间称王，秦国称王自嬴驷始，并重用樗里疾、张仪等人。前325年，惠文王正式称王，随后韩、赵、燕、中山和宋也都先后称王，史称五国相王；同年秦昭襄王生。前311年，惠文王薨，太子秦武王即位。");
            pEntries.Add("qin_kongzi",
                "孔子（前551年9月28日—前479年3月9日），姓子，氏孔，名丘，字仲尼，后世敬称孔子或孔夫子，中国春秋时代鲁国官员、思想家和教育家。孔氏出身宋国贵族，在孔子的三代前移居鲁国。孔子三岁丧父，约三十岁时开始收授门徒，不久后成为鲁国最负盛名的礼学专家，先后担任中都宰、大司寇等职。其后，孔子受到猜忌与排挤，辞职离开鲁国，周游列国十四年，寻求出仕机会，希望国君能采纳其政治主张，但始终未获任用，最后返回鲁国，专心教授弟子与编订经书，直至逝世。");
            pEntries.Add("qin_laozi",
                "李聃（dān）（前571年—不详），李氏，一说姓老，一说姓利，名耳或贞，字耼。据传老聃生于东周的楚国苦县厉乡曲仁里（原属陈国，位于今河南省鹿邑县），师从商容，在春秋时期在东周王国所拥有的守藏室内任柱下史。老聃被认为是中国春秋时代思想家，隐居邢台广阳山。以其名义被撰写出来的《老子》一书被广泛地称为《道德经》，为道家的经典。");
            pEntries.Add("qin_le_yang",
                "乐羊是战国初年魏文侯麾下将领，奉命率军攻打由中山国占据的顾地及其都城。中山君以乐羊之子为质要挟，甚至烹杀其子，乐羊仍坚持围攻三年并最终灭中山。魏文侯战后让他观看装满毁谤奏书的箱子，既嘉奖军功也保持戒备，显示战国君臣间的信任边界。");
            pEntries.Add("qin_le_yi",
                "乐（yuè）毅（约前300年—约前260年），子姓，乐氏，中国战国时期燕国着名军事家，辅佐燕昭王，曾攻下齐国70余城而封昌国君，后获赵国封望诸君。与管仲齐名，是东周战国时期法家重要代表人物之一。乐羊葬于中山国灵寿（属今河北省保定市），后中山为赵所灭。乐毅有贤才，好兵法，甚为赵人器重。");
            pEntries.Add("qin_li_mu",
                "李牧（？—前229年），名繓（zuǒ），字牧，以字行，战国后期军事家，赵国名将，与白起、王翦、廉颇并称战国四名将。李牧驻守代郡、雁门郡期间，率军大破匈奴。在肥之战、番吾之战两次击败秦国，受封武安君，但最终被赵幽缪王杀害。而关于李牧的死因，史料记载也多有不同。");
            pEntries.Add("qin_li_si",
                "李斯 （？—前208年），楚国上蔡（今河南省上蔡县西南方）人，秦朝政治家、文学家和书法家。李斯曾任秦朝丞相，一说左丞相，司马迁着《史记》，为李斯立《李斯列传》。早年为上蔡郡的小吏，负责掌管文书，后和韩非师从荀子学习帝王之术，后来都成为诸子百家中法家学说的代表人物。李斯学成后进入秦国，为秦相吕不韦的舍人，文信侯很赏识李斯，任他做郎官。");
            pEntries.Add("qin_lian_po",
                "廉颇是赵国名将，长期率军与齐、魏、燕交战，并在秦赵对峙中以坚守消耗秦军。他因蔺相如位在己上而不满，得知对方以国事为重后负荆请罪，将相和成为赵国政治团结的象征。晚年廉颇受谗离赵，虽希望重新效力却未能归国，“尚能饭否”遂成为老将失意的典故。");
            pEntries.Add("qin_likui",
                "李悝（kuī）（前455年—前395年），又作李克、李兑等，魏国安邑（今山西省夏县）人。任魏国的相邦，主持变法，其「重农」与「法治」结合的思想对商鞅、韩非影响极大。故一般认为他是法家的始祖。");
            pEntries.Add("qin_lu_buwei",
                "吕不韦（前290年？—前235年），姜姓，吕氏。中国战国时代政治人物，卫国濮阳（今河南濮阳南）人，初为大商人，后来成为秦相，封文信侯，在秦为相十三年。广招门客以「兼儒墨，合名法」为思想中心，合力编撰《吕氏春秋》，有系统性的提出自己的政治主张，后为先秦杂家代表人物之一。执政时曾攻取周、赵、卫的土地，立三川、太原、东郡，对秦王政兼并六国的事业有重大贡献。");
            pEntries.Add("qin_mao_sui",
                "毛遂（？—？），东周战国时期赵国邯郸人（今河北省邯郸市）。为平原君赵胜的门客，战国时期着名说客。毛遂是赵国大臣平原君的门客，其生平不详，其主要事蹟是推动赵、楚两国共同抵抗秦国。");
            pEntries.Add("qin_meng_tian",
                "蒙恬（tián）（约前250年—前210年），中国秦朝将领、书法家，祖居齐国，官至内史，祖父蒙骜和父亲蒙武皆为秦国名将。蒙恬北防匈奴多年，威震北方。秦始皇驾崩后，因为支持公子扶苏，被赵高设计谋害。");
            pEntries.Add("qin_mengchang",
                "孟尝君（？—前279年），妫姓，田氏，名文，字孟，战国四公子之一，齐国的公族。其父靖郭君田婴死后，田文继位薛公于薛城（今山东滕州东南），号孟尝君，以广招宾客、食客三千闻名。孟尝君田文在背后组织与推动的「第二次合纵攻秦之战」（公元前298年—前296年）唯一一次成功攻破函谷关(前线作战的是齐国名将匡章)、迫使秦国割地求和的。");
            pEntries.Add("qin_mengzi",
                "孟子（前372年—前289年），姬姓，孟氏，名轲，邹国（今山东省邹城市）人，战国时期儒家代表人物。其字号在汉代以前的古书未有记载，但曹魏、晋代之后却传出子车、子居、子舆、子展等不同的字号。生卒年月因史传未记载而说法繁多，其中以《孟子世家谱》上所记载之生于周烈王四年（前372年），卒于周赧王二十六年（前289年）较为多数学者采用。孟子之弟子万章与其余弟子着有《孟子》一书。");
            pEntries.Add("qin_mozi",
                "墨子（前468年？—前376年），子姓，墨氏，名翟，春秋末战国初期宋国（今河南商丘）人，一说鲁国（今山东滕州木石镇）人，是中国着名思想家、科学家、教育家、军事家、通才。提出了“非儒”、“兼爱”、“非攻”、“尚贤”、“尚同”、“天志”、“明鬼”、“非命”、“非乐”、“节葬”、“节用”、“交相利”等观点，创立墨家学说，并有《墨子》一书传世。墨家在当时影响很大，墨子因反儒，创立墨学。《墨子》一书中体现的墨子的思想在后世仍具有一定影响，广为流传的《千字文》中便记载了出自《墨子·所染》的「墨悲丝染」的故事。");
            pEntries.Add("qin_mugong",
                "秦穆公（前705年—前621年），部份记载中被称为秦缪公，嬴姓，名任好，春秋时代秦国国君。在位三十九年（前659年－前621年），谥号穆，在《史记》中被认定为春秋五霸之一。秦穆公非常重视人才，其任内获得了百里奚、蹇叔、丕豹及公孙枝等贤臣的辅佐，曾协助晋文公回到晋国夺取君位。周襄王时出兵攻打蜀国和其他位于陇东及陇西一带的国家，开地千里，因而周襄王任命他为西方诸侯之伯，遂称霸于西戎。");
            pEntries.Add("qin_pingyuan",
                "平原君（？—前251年），嬴姓，赵氏，名胜，赵武灵王之子，赵惠文王的弟弟，母不详，是东周战国时期赵国宗室大臣，在赵惠文王和赵孝成王时任宰相，是着名的政治家之一，以善于养士而闻名。和齐国孟尝君田文、魏国信陵君魏无忌、楚国春申君黄歇合称战国四公子。司马迁着《史记》，将平原君与虞卿合立《平原君虞卿列传》，此外，《赵世家》《魏公子列传》《范睢蔡泽列传》《廉颇蔺相如列传》《鲁仲连邹阳列传》等亦散记有其事蹟。");
            pEntries.Add("qin_qu_yuan",
                "屈原（约前340年－前278年），芈姓，屈氏，名平，字原，是中国战国时期楚国的诗人、政治人物。现存最早提及屈原的作品是西汉贾谊的《吊屈原赋》；司马迁《史记·屈原贾生列传》则是现存最早的系统传记，但其中的年代与事迹存在若干矛盾。据《史记》记载，屈原出身楚国宗室，曾任左徒，参与楚怀王时期的内政与外交，主张联齐抗秦，后遭疏远并被放逐。前278年，秦将白起攻破楚都郢。");
            pEntries.Add("qin_ran_geng",
                "冉耕（前544年—？），冉氏，字伯牛。中国春秋时代末鲁国郓城（今山东省菏泽市定陶区冉堌镇）人，是孔子的学生，孔门十哲之一，曾任鲁国的中都宰，孔子很器重他。伯牛患病早逝，孔子十分难过。");
            pEntries.Add("qin_shang_yang",
                "商鞅（前390年—前338年），又称卫鞅或公孙鞅，是战国中期卫国人，公元前4世纪的重要政治家和军事家，也是法家代表人物之一，师从李悝。在秦孝公（前382年—前338年）时期，商鞅对秦国的政治和社会制度进行了深刻改革，使秦国从此逐渐富强，为后来统一六国奠定了基础。商鞅早年学习法家和兵家思想，师从魏国改革设计者李悝，曾任魏国国相公叔痤的中庶子。秦孝公发布求贤令后，商鞅入秦，推行变法改革，使秦国逐渐强盛，史称“商鞅变法”。");
            pEntries.Add("qin_shangwen",
                "商文，田齐公子，《资治通鉴》和《史记》中记载为田文，与孟尝君同名，《吕氏春秋》则作商文，于魏武侯时期与吴起竞争魏国国相一职，后来魏武侯拜商文为相。魏武侯之所以用他，是因为他出身显贵，吴起出身微贱，被认为不能号召百姓。吴起担任西河郡太守，威信很高。魏武侯继位后，许多人都认为吴起能够拜为魏国国相，但最终魏武侯任命商文。");
            pEntries.Add("qin_shen_buhai",
                "申不害（前385年—前337年），尊称申子，中国战国时代郑国京邑（今河南荥阳）人，郑国被韩国所灭之后，以法家学说，成为韩昭侯的宰相，为中国先秦诸子百家中法家『术』派代表人物。申不害大致上二十多岁时为郑国低阶官吏，后韩灭郑国后，申不害以刑名法术的学说向韩昭侯求官，昭侯即位不久，颇具雄心壮志，意图中兴，且用人不拘一格，赏识了申思潮，拜为宰相，他在韩为相国，内修政治、教育，对外应付诸侯，前后近二十年。申不害治国期间，国家富足，军事强大，无他国敢来侵犯韩国。");
            pEntries.Add("qin_shen_dao",
                "慎到（？—？），中国战国时代思想家，赵国人，曾在齐国稷下学宫讲学，着有《慎子》一书。他的思想融合道家与法家，主张「道」是终极实在，对待事物要听其自然；政治上主张君王要有绝对的权力，提出「势」的原则， 君王应建立客观的赏罚制度役使人民，强调君主无为而臣下有为。慎到「势」的学说为韩非所采纳，为法家三派之一。");
            pEntries.Add("qin_shihuang",
                "秦始皇（前259年2月18日—前210年7月11日），嬴姓，名政，史书多作秦王政或始皇帝。嬴姓远祖封地为嬴城（今山东省济南市莱芜区），秦王室先祖自该地区西迁，世居西垂（今甘肃礼县一带），生于赵国首都邯郸（今河北邯郸市），是秦庄襄王及王后赵姬之子，商朝重臣恶来的第35世孙。出土《北京大学藏西汉竹书》第三卷中称其为赵正。唐代司马贞在《史记索隐》引述《世本》称其为赵政。");
            pEntries.Add("qin_su_dai",
                "苏代是战国纵横家，与苏秦同族，长期往来燕、齐、赵等国从事游说。他曾劝赵惠文王停止攻燕，以鹬蚌相争、渔人得利说明秦国可能趁两国交战获利。苏代的活动延续合纵外交传统，也反映小国在齐秦竞争间借说客调整联盟的现实。");
            pEntries.Add("qin_su_qin",
                "苏秦（前382年—前284年），己姓，苏氏，有苏氏之后，字季子，东周雒邑（今河南洛阳东）乘轩里人，相传为鬼谷子徒弟。苏秦与张仪同出自鬼谷子门下，跟随鬼谷子学习纵横之术。学成后，前往秦国游说，结果潦倒而归。随后刻苦攻读《阴符》，一年后游说列国，被燕文公赏识，出使赵国。");
            pEntries.Add("qin_sun_bin",
                "孙膑（前382年—前316年），或说号伯灵，妫姓，孙氏，本名不详，战国中期军事家，兵家代表人物。孙膑出生于阿、鄄之间（今山东省阳谷县阿城镇、菏泽市鄄城县北一带），是孙武的后代。孙膑曾与庞涓为同窗，因受庞涓迫害遭受膑刑，身体残疾，后在齐国使者的帮助下投奔齐国，被齐威王任命为军师，辅佐齐国大将田忌两次击败庞涓，取得桂陵之战和马陵之战的胜利，奠定齐国的霸业。明末清初有以孙膑、庞涓生平为原型的历史小说《孙庞斗志演义》，使孙庞斗智的故事广为流传。");
            pEntries.Add("qin_sun_wu",
                "孙武（前545年—前470年或前496年），妫姓，孙氏，名武，字长卿，春秋时期齐国人，陈胡公的直系后代，着名军事家、政治家，兵家代表人物。兵书《孙子兵法》的作者，后人尊称为孙子、兵圣、东方兵圣，山东、苏州等地尚有祀奉孙武的庙宇兵圣庙。其族人为乐安孙氏始祖，次子孙明为富春孙氏始祖。");
            pEntries.Add("qin_tian_dan",
                "田单是齐国宗室远支，燕将乐毅攻占齐国大部时，他退守即墨并被军民推举为守将。他利用反间计促使燕惠王撤换乐毅，又以火牛阵发动夜袭，击溃燕军并连续收复七十余城，迎回齐襄王。田单因复国之功受封安平君、出任齐相，后来又曾入赵为将，其事迹成为战国守城反攻的经典战例。");
            pEntries.Add("qin_tian_ji",
                "田忌是战国齐国宗室将领，在桂陵之战中采纳孙膑“围魏救赵”的方案，避开魏军主力而迫使庞涓回援。马陵之战时他继续担任齐军统帅，以减灶诱敌配合伏击，重创魏军并扭转齐魏力量对比。此卡记录的是田忌直接统军、执行孙膑作战计划的将领身份，重点在两次大战中的指挥职责。此卡侧重田忌担任齐国统帅、采纳孙膑谋略参加桂陵与马陵战事的军职身份。");
            pEntries.Add("qin_tianji",
                "田忌长期参与齐国军政，因赛马屡败而接受孙膑调整上中下等马匹出场顺序的建议，最终以整体配对赢得赌赛。他由此认识孙膑的才能并将其推荐给齐威王，使孙膑得以进入齐国军事决策核心。此卡侧重田忌识才荐贤及其与齐威王的政治关系，与另一张强调桂陵、马陵统兵经历的卡片分别记录。此卡侧重田忌与齐威王赛马的知人用谋故事，以及他推荐孙膑进入齐国军政核心的经历。");
            pEntries.Add("qin_wang_ben",
                "王贲是秦国名将王翦之子，秦统一战争后期独立统率大军攻灭东方诸国。秦王政二十二年他引黄河、鸿沟水灌大梁，迫使魏王假投降；随后又北上攻取辽东，俘获燕王喜。秦王政二十六年王贲与李信攻齐，齐王建不战而降，六国统一后他因功受封通武侯。");
            pEntries.Add("qin_wang_jian",
                "王翦（jiǎn）（？—？），战国时期秦国名将，关中频阳东乡（今陕西富平东北）人，主要战绩：破赵国都城邯郸，消灭燕和赵；以秦国绝大部分兵力消灭楚国后，接着率领平楚大军南下平定百越。王翦与白起、廉颇、李牧并称战国四大名将。其曾孙是琅琊王氏和太原王氏的始祖。");
            pEntries.Add("qin_wei_liao",
                "尉缭（？—？），姓氏不知，名缭，战国时代魏国大梁人，后入秦成为秦国国尉，因而被称为尉缭，为秦始皇统一六国立下汗马功劳，杨宽《战国史》中，考证顿弱即是尉缭的另一个名字。秦王政十年（公元前237年），嬴政见尉缭后，替尉缭准备与自己相同规格的衣服和膳食。尉缭认为秦王政的面相刚烈，有求于人时可以虚心诚恳，一旦被冒犯时却会变得极其残暴，对敌人也毫不手软。尉缭认为这样的秦王政欠缺照顾天下百姓的仁德之心，不能长久来往。");
            pEntries.Add("qin_wu_qi",
                "吴起（前440年—前381年），中国春秋末期战国初期军事家、政治家、改革家，兵家代表人物。衞国左氏（今山东省菏泽市定陶县，一说山东省菏泽市曹县东北）人。吴起历侍鲁、魏、楚三国，通晓兵家、法家、儒家三家思想，在内政、军事上都有极高的成就。仕鲁时曾击退齐国的入侵；仕魏时屡次破秦，尽取秦国的河西地区（今山西、陕西两省间黄河南段以西地区），成就魏文侯的霸业；仕楚时主持改革，史称吴起变法。");
            pEntries.Add("qin_wuwang",
                "秦武王（前329年—前307年），《史记·秦始皇本纪》作秦悼武王，《世本》作秦武烈王，《越绝书》作秦元武王，嬴姓《史记索隐·秦本纪》记载名荡，战国时期秦国君主。前311年，秦惠文王去世，其子秦武王继位。在秦武王尚为太子时就不喜欢张仪，等到他继承王位后，很多大臣在秦武王面前指责张仪说他为人不讲信用、反复无常，以卖国谋图恩宠，如果大王要再任用他，恐怕被天下人所耻笑。前310年，秦武王将张仪、魏章驱逐至魏国。");
            pEntries.Add("qin_wuzi",
                "伍子胥（前559年—前484年），伍氏。名员（yún），字子胥，以字行，后投奔吴国，封于申，因此又叫申胥。伍子胥家族因在楚国被迫害，投奔吴国。受吴王阖闾重用，大破楚国，北镇齐晋，南服越人，官拜相国公。");
            pEntries.Add("qin_xiaogong",
                "秦孝公（前382年—前338年），《越绝书》作秦平王，嬴姓，《史记索隐》记载名渠梁。战国时期秦国君主，秦献公之子，前362年－前338年在位，在位共25年。秦孝公在位期间致力于恢复秦穆公时的霸业，他因此颁布着名的求贤令，任用商鞅进行变法，将秦国改造成为富裕强大之国，为秦国将来兼并六国、统一中国奠定了基础。");
            pEntries.Add("qin_xiaowenwang",
                "秦孝文王（前302年—前250年11月14日），即位前称安国君，嬴姓，《史记索隐》记载名柱，《广弘明集》引《陶公年纪》记载名式，战国时期秦国君主。秦昭襄王与唐太后之子，正式改元后三天去世，实际统治不足一年。秦昭襄王在位时，秦孝文王被封为安国君。秦悼太子于前267年死于魏国后，安国君于前265年被立为太子。");
            pEntries.Add("qin_xin_ling_jun",
                "信陵君魏无忌是魏昭王之子、魏安釐王之弟，以礼贤下士招揽侯嬴、朱亥等门客，与其他三位封君并称战国四公子。秦军围赵都邯郸时，他借魏王兵符并令朱亥击杀晋鄙，夺军救赵，最终联合诸侯击退秦军。此后他一度留赵，归魏后又组织五国联军在河外击败秦将蒙骜，但因秦国反间和魏王猜忌被解除兵权。");
            pEntries.Add("qin_xunzi",
                "荀子（约公元前316年—约公元前237年至公元前235年），名况，被尊称为荀卿，又称孙卿，中国战国时代儒家学者和思想家，赵国人，曾担任齐国稷下学宫祭酒、楚国兰陵令，到赵国、秦国游说诸侯，宣扬儒学和传授六经，批评子思、孟子等其他儒者及墨家、道家等其他学派，有韩非、李斯等弟子，着作后世编为《荀子》一书。作为先秦儒家代表人物，与孔子、孟子合称孔孟荀。荀子祖述孔子，重视道德伦理，提倡仁义、礼义和忠信，集先秦礼论之大成，重视以礼修身和礼制教育。他相信性恶论，人与生俱来本无道德，若放纵情欲不加节制，将互相仇恨和斗争；道德价值是后天人为建构的，由圣人创造，以规范和美化人性。");
            pEntries.Add("qin_yan_hui",
                "颜回（前521年—前481年），曹姓，颜氏，字子渊，又称颜子、颜渊。唐代为避李渊名讳，曾改其字为子泉。是小邾国公子友的十七世子孙，孔子七十二门徒之首。被视作孔子最得意的弟子，位居孔门第一位。");
            pEntries.Add("qin_yan_sui",
                "燕遂被卡库置于战国后期赵国的政治人物序列，其活动背景是赵国在秦国持续进攻下调整用人与外交。相关传世材料对其生平、官职和具体事迹记载十分零散，不能据此附会为同名的其他时代人物。本卡保留这一独立身份，并明确把可确认范围限定在战国赵国政治活动之内。");
            pEntries.Add("qin_yan_ying",
                "晏婴（前578年—前500年），字仲，谥平，习惯上多称晏平仲，亦称晏子。齐国莱地夷维人，祖籍为宋国。晏婴的父亲晏弱为宋穆公的曾孙，因宋国内乱而到齐国担任上大夫，被齐国赏赐以莱地作为封地。据说晏婴身材短小，其貌不扬，但头脑机敏，能言善辩。");
            pEntries.Add("qin_zhang_yi",
                "张仪（前373年—前310年），姬姓，张氏，魏国安邑（今山西夏县）人，战国时期着名的纵横家。提倡连横，即秦国联合其他诸侯国中的几个，然后对抗其他的诸侯国，多次破坏了公孙衍的合纵，为秦惠王重用，封武信君，卒于魏国。张仪是魏国王族支庶子弟，和苏秦同为鬼谷子的徒弟。张仪学成之后游说诸侯，任楚国相国昭阳的门下客。");
            pEntries.Add("qin_zhao_kuo",
                "赵括（？—— —前260年），战国时期赵国的将领。其父为赵国名将马服君赵奢，故称马服子。赵括（？—— ），战国时期赵国的将领。");
            pEntries.Add("qin_zhao_she",
                "赵奢原是赵国征收田租的官员，因依法处置平原君家拒税人员而获赏识，随后被推荐管理全国赋税。他领兵救援阏与时以隐蔽行军、抢占北山和集中兵力击败秦军，打破秦军不可战胜的声势。战后赵奢受封马服君，与廉颇、蔺相如并列，其子赵括后来继承名望却在长平之战失败。");
            pEntries.Add("qin_zhaoxiangwang",
                "秦昭襄王（前325年—前251年），嬴姓，名稷，秦惠文王之子，秦悼武王（简称秦武王）之弟。在位时间长达56年（前41年与母亲宣太后主政辅政），在他数十年的统治下，期间任用包括魏冉、范雎、白起等名臣，治军备战，富国强兵，为其曾孙秦始皇奠定将来一统天下的基础。前307年，秦武王意外身亡，诸兄弟争位；赵武灵王与秦国的魏冉等大臣合谋，于是得立，是为秦昭襄王，简称秦昭王。秦昭襄王在位时，秦国继续扩张，最着名之西元前260年打败赵国的长平之战就是在其在位晚期发生的。");
            pEntries.Add("qin_zhuangxiangwang",
                "秦庄襄王（前281年—前247年7月6日），《史记》记载名为子楚，《水经注·卷十九·渭水下》作秦庄王，《太平寰宇记·卷二十五·雍州》作秦襄王。嬴姓，名子楚，《战国策》记载原名子异、异人，战国时期秦国君主。秦孝文王与夏姬之子，在位3年。他是秦始皇的父亲，中国第一位太上皇（追尊）。");
            pEntries.Add("qin_zhuangzi",
                "庄子（约前369年—前286年），庄氏，名周，一说字子休，约与孟子同时，宋国蒙人（今山东省菏泽市东明县），曾任漆园吏。为中国战国中期思想家、哲学家、文学家，是道家学派的代表人物，老子思想的继承和发展者，后世将他和老子并称为「老庄」。在西元742年，唐玄宗天宝初，诏封庄周为南华真人，称其着书《庄子》为南华经，在四库全书之中归类为子部道家类。宋徽宗时，他被追封为「微妙元通真君」。");
            pEntries.Add("qin_zichan",
                "子产名侨，是春秋郑国公族和执政者，在晋楚争霸夹缝中主持郑国政务二十余年。他整顿田界与赋税、公布成文刑书，并通过谨慎外交维持小国生存；面对乡校议政，他主张保留公共议论以了解施政得失。子产重视礼法又能因时改革，去世后郑人哀悼，孔子称赞他具有古人仁爱之风。");
            pEntries.Add("qin_zixia",
                "卜商（前507年—？），姒姓，卜氏，名商，字子夏。晋国贵族之后，但到他这一代已家道中落。家贫，勤奋好学，是孔子的重要弟子，少孔子四十四岁，与子游同列孔门十哲的文学科，长于文学，对《诗经》有深入的研究。曾任鲁国莒父宰，后在魏国西河（今陕西渭南）创办学堂并授业，魏文侯曾向子夏问问题。");
            pEntries.Add("qin_ziying",
                "子婴（？—前206年1月），嬴姓，一说名婴，为秦朝皇帝，刘邦称其为秦降王，后世亦称其为秦三世，是秦朝末代君主。性格仁爱且节制，秦二世皇帝胡亥在位时，子婴曾为二世杀害兄弟、功臣之事向二世进谏。胡亥被弑后，中丞相赵高迎立子婴继位，子婴即位5日便设计诛杀赵高，并诛其族。《史记》指之所以诛灭赵高，是因为他企图招引义军到咸阳及承诺杀死所有秦朝宗室取而代之，子婴得知就先下手杀死他，《赵正书》则指赵高为章邯所杀。");
            pEntries.Add("qin_ziyou",
                "言偃（前504年—前443年）又称言子，字子游，春秋时期孔子弟子。司马迁《史记》称其为“吴人”，又说其“习于文学”，曾任武城宰。后世多将其列为孔门十哲之一，并被视为孔门文学科的重要代表人物。");
            pEntries.Add("qin_zou_yang",
                "邹阳（？—前120年），西汉散文家，齐国人。邹阳，先与庄忌、枚乘等人游于吴王刘濞门下，在当时以口辩着称。后来见刘濞有反叛的迹象，作《上吴王书》陈说利害以劝谏之。");
            pEntries.Add("qin_zouji",
                "邹忌（？—？），中国战国时代齐国人。《史记》中亦作驺忌，齐威王时为相，后封于下邳（今江苏省睢宁县古邳镇），号成侯。邹忌时期，齐国先后取得了桂陵之战、桑丘之战、马陵之战等胜利，徐州相王后齐国国君开始称王，多国朝于齐国。但邹忌也曾阻止齐国救赵、救韩，并因将相失和而一度逼走田忌。");
            pEntries.Add("shang_dixin",
                "帝辛（？—前1046年？），子姓，殷氏之始，名受，一名受德，后史随从周人称他为纣王、商纣王、殷纣王，是商朝末任君主。夏商周断代工程认为他在前1075年至前1046年在位。帝辛非常重视农业和生产力发展，实施社会变革，使其国力强盛。在位期间，他持续对东南方的人方（东夷）用兵，直至彻底击败，使商疆域扩至江淮一带。");
            pEntries.Add("shang_diyi",
                "帝乙（？—前1076年？），子姓，名羡，商朝晚期国王，末代商王帝辛（纣）之父。具体在位年代不详，约在西元前11世纪之初。夏商周断代工程定为前1101年－前1076年。");
            pEntries.Add("shang_pangeng",
                "盘庚（？—前1277），商朝中后期君主。商汤九代孙，帝祖丁之子，帝阳甲之弟，《太平御览》引《史记》称其在位28年。夏商周断代工程把盘庚时期定在前1300年左右。");
            pEntries.Add("shang_taijia",
                "商太宗太甲（？—？），子姓，名至，商汤的长孙，又称祖甲，《史记》记载其庙号为太宗，是商朝第五位君王。据《史记》记载，太甲在位初年，任用伊尹为相，商朝比较强盛。可是太甲三年时，太甲开始按照自己性子办事，以残暴的手段对付百姓、奴隶，伊尹便把太甲流放到桐之宫。三年后，伊尹见太甲改过自新，便郑重地将政权交返给太甲。");
            pEntries.Add("shang_tang",
                "汤（约前17世纪—前16世纪），商朝开国之君，子姓，名履，今人多称商汤、殷汤，又称武汤、天乙、成汤、成唐，商代金文和甲骨文称为唐、成、大乙，原商部落首领，与有莘氏通婚后，任贤臣伊尹和仲虺为左右相，以亳为前进据点，积极治国，准备灭夏朝。当夏桀之时，夏王内政不修，外患不断，夏后氏的共主地位严重动摇。汤乘机起兵，首先攻灭葛（今河南宁陵县北）及十多小国和部落。接着又克韦（今河南滑县东南）、顾（今山东菏泽鄄城东南）、昆吾（今河南许昌东部）等小国。");
            pEntries.Add("shang_wuding",
                "武丁是商代后期君主，传说即位前曾在民间生活，继位后任用傅说、甘盘等人整顿王朝政务。他多次向土方、鬼方、羌方等周边方国用兵，王后妇好也以统帅和祭司身份参与战争与礼仪。殷墟甲骨卜辞保存了武丁时期大量征伐、祭祀和生产记录，这一阶段通常被视为晚商国力最强盛的时期。");
            pEntries.Add("wei_wenhou",
                "魏文侯（？—前396年），安邑（今山西夏县）人。姬姓，魏氏，名斯（《史记·魏世家》记其名为都）。周贞定王二十四年（前445年）继魏桓子位，周威烈王二年（前424年）称侯改元，威烈王二十三年（前403年）与韩、赵两家一起被周威烈王册封为诸侯，是为三家分晋，周安王六年（前396年）卒。魏文侯是魏桓子之子，魏国百年霸业的开创者。");
            pEntries.Add("wu_helv",
                "吴王阖闾名光，是春秋晚期吴国君主，在伍子胥、孙武等人辅佐下改革军政并扩张国力。他派军攻破楚国都城郢，吴国由此进入强盛阶段，也深度介入楚、越争霸。阖闾后来在槜李之战中被越王勾践军击伤而死，其子夫差继承了对越战争。");
            pEntries.Add("xia_jie",
                "桀（jié），姒姓，夏后氏，名履癸，又称夏桀，中国夏朝第十七任君主，亦是最后一任君主。桀身体强壮，能够赤手空拳搏虎豹。后世的文献将他描述成一个昏君：他宠信王后妺喜，对政事不闻不问之余，还大量残杀忠良，以炮烙杀大臣关龙逢。《通监外纪》记载：“桀作瑶台，罢民力，殚民财。");
            pEntries.Add("xia_qi",
                "启（？—？），姒姓，夏后氏，名啓，是中国夏朝第二任首领。治水英雄禹的儿子，母亲是涂山氏族的女子。儿子至少有五人，其中有太康及仲康。据《竹书纪年》，启在位39年，78岁驾崩。");
            pEntries.Add("xia_shaokang",
                "少康（？—？），姒姓，夏后氏，中国夏朝第六任君主。传说寒浞派人杀死相后，相的妃子后缗逃到娘家有仍氏（任姓，在今山东省济宁市任城区），生下少康。少康长大后为有仍氏牧正，又逃至有虞氏（今河南商丘虞城南）任庖正（掌厨），有虞氏的君主虞思把两个女儿“二姚”嫁给了少康，有田一成（方十里），有众一旅（五百人）。夏朝遗臣靡集结夏朝斟灌氏及斟寻氏二国遗民之力，灭寒浞，立少康为王。");
            pEntries.Add("xia_taikang",
                "太康（？—？），姒姓，夏后氏，启之子。《太平御览》引《帝王世纪》记载太康在位二十九年。《竹书纪年》称太康的都城在斟寻（一作斟鄩）。据说太康终日沉迷打猎，不理政事，结果去洛水北岸游猎时，为有穷氏部落首领后羿所逐，不得返国，在阳夏（今河南省太康县西）居十年而病死。");
            pEntries.Add("xia_yu",
                "禹（yǔ）（？-？），姒姓，夏后氏，传说名文命，后世尊称为大禹。远古时期中国神话人物，是黄帝轩辕氏八世孙，因在大禹治水中成功治理洪水之患的故事而广为人知。禹在尧时被封为夏伯，故史书又称伯禹、夏禹。在道教信仰里，禹也被尊为水官大帝、水仙尊王。");
            pEntries.Add("yan_zhaowang",
                "姬职在燕国内乱和齐军占领后被拥立，是战国时期的燕昭王。他修筑黄金台、礼遇郭隗，并招揽乐毅、邹衍、剧辛等人才重建军政。乐毅随后统率五国联军攻破齐国七十余城，秦开又向东北击退东胡，燕国国势由衰败转入强盛。");
            pEntries.Add("yue_goujian",
                "勾践（？—前464年），又写作句践；在出土文物「越王勾践剑」里写为鸠浅；司马贞《史记索隐》引《纪年》作菼执，是中国春秋时代后期的越国君主。有关他的先世，有说「其先禹之苗裔」，亦有说「先世无所考」，也有说他是「祝融之后」并且是楚国的芈姓，众说纷纭。勾践生年不详，前496年至前464年在位。");
            pEntries.Add("zhao_wulingwang",
                "赵武灵王（前356年—前295年），嬴姓，赵氏，名雍，中国战国中后期赵国的君主。生于赵成侯十九年（前356年），在位共27年（前326至前299年），推行“胡服骑射”政策，赵国因而得以强盛，灭中山国，败林胡、楼烦二族，辟云中、雁门、代三郡，并修筑“赵长城”。武灵王禅让王位予赵何，即赵惠文王，自己退居幕后，号称「主父」。因为储君废立问题，在赵惠文王四年（前295年）的沙丘之乱中被幽禁而饿死。");
            pEntries.Add("zhou_chengwang",
                "周成王（约前1056年—前1025年），姬姓，名诵，西周第二代天子，周武王之子。相传成王即位之初，由叔父周公旦摄政，引起管叔和蔡叔不满，联合武庚发动叛乱，周公出兵平定三监之乱。成王亲政后，营造新都雒邑、大封诸侯，还命周公东征、编写礼乐，加强西周王朝的统治。近代中国大陆夏商周断代工程，将成王在位时间定为前1042年至前1021年，共22年。");
            pEntries.Add("zhou_huanwang",
                "周桓王姬林继承周平王，是东周第二位天子，当时王室土地和号召力已明显衰落。他试图削弱郑庄公在王朝中的权力并收回郑国占据的土地，双方关系由政治对抗发展为公开战争。繻葛之战中周王联军被郑军击败，桓王本人中箭受伤，此役进一步暴露东周天子难以约束强大诸侯的现实。");
            pEntries.Add("zhou_kangwang",
                "周康王（约前1040年—前996年），姬姓，名钊，西周第三代天子，周成王之子。周康王与其父周成王统治期间，社会安定、百姓和睦、“刑错四十余年不用”，被誉为成康之治。《太平御览》引《帝王世纪》和《通鉴外纪》均记载周康王在位26年。近代中国大陆夏商周断代工程，则将周康王在位时间定为前1020年至前996年，共25年。");
            pEntries.Add("zhou_liwang",
                "周厉王（前890年—前828年），姬姓，名胡，在西周青铜器铭文中。《史记》作厉王，西周青铜器铭文作剌王，在文献中又作汾王。国人暴动之后，他居住在今山西省汾河流域，因此传世典籍和青铜器铭文又称他为汾王 。厉王为西周第十位君王，约前877年－前841年在位，计37年；连同共和的十四年，在位约49年。");
            pEntries.Add("zhou_muwang",
                "周穆王（？—约前922年），又作周缪王，姬姓，名满，周昭王之子，西周第五代天子。在位时间约为55年（夏商周断代工程定为前976年－前922年，一说前1001年－前947年）。2019年，张鹏程的研究认为周穆王前957年－前918年在位，共四十年。");
            pEntries.Add("zhou_pingwang",
                "周平王（？—前720年4月16日），姓姬，名宜臼，东周第一位天子。周幽王之子，母申后为申侯之女，后母褒姒。王子宜臼本是周幽王太子，后因周幽王宠爱美女褒姒，褒姒生下一子伯服，得宠更甚。");
            pEntries.Add("zhou_xuanwang",
                "周宣王（约前862年—前782年），姬姓，名静，一作靖。西周第十一代天子，周厉王之子，在位46年。周宣王继位后，政治上任用召穆公、尹吉甫、仲山甫、程伯休父、虢文公、申伯、韩侯、显父、仍叔、张仲一帮贤臣辅佐朝政；军事上借助诸侯之力，任用南仲、召穆公、尹吉甫、方叔陆续讨伐猃狁、西戎、淮夷、徐国和楚国，使西周的国力得到短暂恢复，史称“宣王中兴”。但周宣王晚年对外用兵接连受挫，尤其在千亩之战大败于姜戎，南国（今长江与汉江之间的地区）之师全军覆没，加之独断专行、不进忠言、滥杀大臣，宣王中兴遂成昙花一现，也为西周在周幽王时期的灭亡埋下了伏笔。");
            pEntries.Add("zhou_youwang",
                "周幽王（前796年？—前771年），姬姓，名宫涅，《史记》作宫湦（shēng）。周宣王之子，西周第十二代君王，也是西周的亡国之君。自前782年至前771年间在位，共11年，谥幽。");
            pEntries.Add("zhou_zhaowang",
                "姬瑕是西周第四位天子，继承成康时期的王朝秩序后多次向南方荆楚地区用兵。他的南征旨在控制汉水交通、获取资源并扩大周王室对南方诸侯的影响。最后一次渡汉水时周军遭遇重大失败，昭王溺亡，王室军事威望受到打击。");
        }
    }
}
